func findTranscriptForSession(sessionID, repoRoot string) (string, error) {
	// Get the agent
	ag, err := GetAgent()
	if err != nil {
		return "", fmt.Errorf("failed to get agent: %w", err)
	}

	// Get the session directory for this agent
	sessionDir, err := ag.GetSessionDir(repoRoot)
	if err != nil {
