   111→func runRewindInteractive() error {
   112→	// Skip on default branch for strategies that don't allow it
   113→	if skip, _ := ShouldSkipOnDefaultBranchForStrategy(); skip {
   114→		fmt.Println("Entire tracking is disabled on the default branch for this strategy.")
   115→		fmt.Println("Create a feature branch to use Entire's rewind functionality.")
   116→		return nil
   117→	}
   118→
   119→	// Get the configured strategy
   120→	start := GetStrategy()
   121→
   122→	// Check for uncommitted changes first
   123→	canRewind, changeMsg, err := start.CanRewind()
   124→	if err != nil {
   125→		return fmt.Errorf("failed to check for uncommitted changes: %w", err)
   126→	}
   127→	if !canRewind {
   128→		fmt.Println(changeMsg)
   129→		return nil
   130→	}
   131→
   132→	// Get rewind points from strategy
   133→	points, err := start.GetRewindPoints(20)
   134→	if err != nil {
   135→		return fmt.Errorf("failed to find rewind points: %w", err)
   136→	}
   137→
   138→	if len(points) == 0 {
   139→		fmt.Println("No rewind points found.")
   140→		fmt.Println("Rewind points are created automatically when Claude Code sessions end.")
   141→		return nil
   142→	}
   143→
   144→	// Check if there are multiple sessions (to show session identifier)
   145→	sessionIDs := make(map[string]bool)
   146→	for _, p := range points {
   147→		if p.SessionID != "" {
   148→			sessionIDs[p.SessionID] = true
   149→		}
   150→	}
   151→	hasMultipleSessions := len(sessionIDs) > 1
   152→
   153→	// Build options for the select menu
   154→	options := make([]huh.Option[string], 0, len(points)+1)
   155→	for _, p := range points {
   156→		var label string
   157→		timestamp := p.Date.Format("2006-01-02 15:04")
   158→
   159→		// Build session identifier for display when multiple sessions exist
   160→		sessionLabel := ""
   161→		if hasMultipleSessions && p.SessionPrompt != "" {
   162→			// Show truncated prompt to identify the session
   163→			sessionLabel = fmt.Sprintf(" [%s]", sanitizeForTerminal(p.SessionPrompt))
   164→		}
   165→
   166→		switch {
   167→		case p.IsLogsOnly:
   168→			// Committed checkpoint - show commit sha (this is the real user commit)
   169→			shortID := p.ID
   170→			if len(shortID) >= 7 {
   171→				shortID = shortID[:7]
   172→			}
   173→			label = fmt.Sprintf("%s (%s) %s%s", shortID, timestamp, sanitizeForTerminal(p.Message), sessionLabel)
   174→		case p.IsTaskCheckpoint:
   175→			// Task checkpoint (uncommitted) - no sha shown
   176→			label = fmt.Sprintf("        (%s) [Task] %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
   177→		default:
   178→			// Shadow checkpoint (uncommitted) - no sha shown (internal commit)
   179→			label = fmt.Sprintf("        (%s) %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
   180→		}
   181→		options = append(options, huh.NewOption(label, p.ID))
   182→	}
   183→	options = append(options, huh.NewOption("Cancel", "cancel"))
   184→
   185→	var selectedID string
   186→	form := NewAccessibleForm(
   187→		huh.NewGroup(
   188→			huh.NewSelect[string]().
   189→				Title("Select a checkpoint to restore").
   190→				Description("Your working directory will be restored to this checkpoint's state").
   191→				Options(options...).
   192→				Value(&selectedID),
   193→		),
   194→	)
   195→
   196→	if err := form.Run(); err != nil {
   197→		return fmt.Errorf("selection cancelled: %w", err)
   198→	}
   199→
   200→	if selectedID == "cancel" {
   201→		fmt.Println("Rewind cancelled.")
   202→		return nil
   203→	}
   204→
   205→	// Find the selected point
   206→	var selectedPoint *strategy.RewindPoint
   207→	for _, p := range points {
   208→		if p.ID == selectedID {
   209→			pointCopy := p
   210→			selectedPoint = &pointCopy
   211→			break
   212→		}
   213→	}
   214→
   215→	if selectedPoint == nil {
   216→		return errors.New("rewind point not found")
   217→	}
   218→
   219→	shortID := selectedPoint.ID
   220→	if len(shortID) > 7 {
   221→		shortID = shortID[:7]
   222→	}
   223→
   224→	// Show what was selected
   225→	switch {
   226→	case selectedPoint.IsLogsOnly:
   227→		// Committed checkpoint - show sha
   228→		fmt.Printf("\nSelected: %s %s\n", shortID, sanitizeForTerminal(selectedPoint.Message))
   229→	case selectedPoint.IsTaskCheckpoint:
   230→		// Task checkpoint - no sha
   231→		fmt.Printf("\nSelected: [Task] %s\n", sanitizeForTerminal(selectedPoint.Message))
   232→	default:
   233→		// Shadow checkpoint - no sha
   234→		fmt.Printf("\nSelected: %s\n", sanitizeForTerminal(selectedPoint.Message))
   235→	}
   236→
   237→	// Handle logs-only points with a sub-choice menu
   238→	if selectedPoint.IsLogsOnly {
   239→		return handleLogsOnlyRewindInteractive(start, *selectedPoint, shortID)
   240→	}
   241→
   242→	// Preview rewind to show warnings about files that will be deleted
   243→	preview, previewErr := start.PreviewRewind(*selectedPoint)
   244→	if previewErr == nil && preview != nil && len(preview.FilesToDelete) > 0 {
   245→		fmt.Fprintf(os.Stderr, "\nWarning: The following untracked files will be DELETED:\n")
   246→		for _, f := range preview.FilesToDelete {
   247→			fmt.Fprintf(os.Stderr, "  - %s\n", f)
   248→		}
   249→		fmt.Fprintf(os.Stderr, "\n")
   250→	}
   251→
   252→	// Confirm rewind
   253→	var confirm bool
   254→	description := fmt.Sprintf("This will reset to: %s\nChanges after this point may be lost!", selectedPoint.Message)
   255→	confirmForm := NewAccessibleForm(
   256→		huh.NewGroup(
   257→			huh.NewConfirm().
   258→				Title(fmt.Sprintf("Reset to %s?", shortID)).
   259→				Description(description).
   260→				Value(&confirm),
   261→		),
   262→	)
   263→
   264→	if err := confirmForm.Run(); err != nil {
   265→		return fmt.Errorf("confirmation cancelled: %w", err)
   266→	}
   267→
   268→	if !confirm {
   269→		fmt.Println("Rewind cancelled.")
   270→		return nil
   271→	}
   272→
   273→	// Perform the rewind using strategy
   274→	if err := start.Rewind(*selectedPoint); err != nil {
   275→		return err
   276→	}
   277→
   278→	// Handle transcript restoration differently for task checkpoints
   279→	var sessionID string
   280→	var transcriptFile string
   281→
   282→	if selectedPoint.IsTaskCheckpoint {
   283→		// For task checkpoint: read checkpoint.json to get UUID and truncate transcript
   284→		checkpoint, err := start.GetTaskCheckpoint(*selectedPoint)
   285→		if err != nil {
   286→			fmt.Fprintf(os.Stderr, "Warning: failed to read task checkpoint: %v\n", err)
   287→			return nil
   288→		}
   289→
   290→		sessionID = checkpoint.SessionID
   291→
   292→		if checkpoint.CheckpointUUID != "" {
   293→			// Truncate transcript at checkpoint UUID
   294→			if err := restoreTaskCheckpointTranscript(start, *selectedPoint, sessionID, checkpoint.CheckpointUUID); err != nil {
   295→				fmt.Fprintf(os.Stderr, "Warning: failed to restore truncated session transcript: %v\n", err)
   296→			} else {
   297→				fmt.Printf("Rewound to task checkpoint. %s\n", formatResumeCommand(sessionID, selectedPoint.Agent))
   298→			}
   299→			return nil
   300→		}
   301→	} else {
   302→		// For session checkpoint: restore full transcript
   303→		sessionID = extractSessionIDFromMetadata(selectedPoint.MetadataDir)
   304→		transcriptFile = filepath.Join(selectedPoint.MetadataDir, paths.TranscriptFileNameLegacy)
   305→	}
   306→
   307→	// Try to restore using GetSessionLog first (for strategies that store transcripts in git)
   308→	// Use checkpoint ID if available (auto-commit strategy), otherwise use commit ID (manual-commit strategy)
   309→	lookupID := selectedPoint.CheckpointID
   310→	if lookupID == "" {
   311→		lookupID = selectedPoint.ID
   312→	}
   313→	if returnedSessionID, err := restoreSessionTranscriptFromStrategy(start, lookupID, sessionID, selectedPoint.Agent); err != nil {
   314→		// Fall back to local file
   315→		if err := restoreSessionTranscript(transcriptFile, sessionID, selectedPoint.Agent); err != nil {
   316→			fmt.Fprintf(os.Stderr, "Warning: failed to restore session transcript: %v\n", err)
   317→			fmt.Fprintf(os.Stderr, "  Source: %s\n", transcriptFile)
   318→			fmt.Fprintf(os.Stderr, "  Session ID: %s\n", sessionID)
   319→		}
   320→	} else {
   321→		// Use session ID returned from strategy (may differ from what we extracted from metadata path)
   322→		sessionID = returnedSessionID
   323→	}
   324→
   325→	fmt.Printf("Rewound to %s. %s\n", shortID, formatResumeCommand(sessionID, selectedPoint.Agent))
   326→	return nil
   327→}
