   387→func runRewindToInternal(commitID string, logsOnly bool, reset bool) error {
   388→	// Skip on default branch for strategies that don't allow it
   389→	if skip, _ := ShouldSkipOnDefaultBranchForStrategy(); skip {
   390→		return errors.New("entire tracking is disabled on the default branch for this strategy - create a feature branch to use rewind")
   391→	}
   392→
   393→	start := GetStrategy()
   394→
   395→	// Check for uncommitted changes (skip for reset which handles this itself)
   396→	if !reset {
   397→		canRewind, changeMsg, err := start.CanRewind()
   398→		if err != nil {
   399→			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
   400→		}
   401→		if !canRewind {
   402→			return fmt.Errorf("%s", changeMsg)
   403→		}
   404→	}
   405→
   406→	// Get rewind points
   407→	points, err := start.GetRewindPoints(20)
   408→	if err != nil {
   409→		return fmt.Errorf("failed to find rewind points: %w", err)
   410→	}
   411→
   412→	// Find the matching point (support both full and short commit IDs)
   413→	var selectedPoint *strategy.RewindPoint
   414→	for _, p := range points {
   415→		if p.ID == commitID || (len(commitID) >= 7 && len(p.ID) >= 7 && strings.HasPrefix(p.ID, commitID)) {
   416→			pointCopy := p
   417→			selectedPoint = &pointCopy
   418→			break
   419→		}
   420→	}
   421→
   422→	if selectedPoint == nil {
   423→		return fmt.Errorf("rewind point not found: %s", commitID)
   424→	}
   425→
   426→	// Handle reset mode (for logs-only points)
   427→	if reset {
   428→		return handleLogsOnlyResetNonInteractive(start, *selectedPoint)
   429→	}
   430→
   431→	// Handle logs-only restoration:
   432→	// 1. For logs-only points, always use logs-only restoration
   433→	// 2. If --logs-only flag is set, use logs-only restoration even for checkpoint points
   434→	if selectedPoint.IsLogsOnly || logsOnly {
   435→		return handleLogsOnlyRewindNonInteractive(start, *selectedPoint)
   436→	}
   437→
   438→	// Preview rewind to show warnings about files that will be deleted
   439→	preview, previewErr := start.PreviewRewind(*selectedPoint)
   440→	if previewErr == nil && preview != nil && len(preview.FilesToDelete) > 0 {
   441→		fmt.Fprintf(os.Stderr, "\nWarning: The following untracked files will be DELETED:\n")
   442→		for _, f := range preview.FilesToDelete {
   443→			fmt.Fprintf(os.Stderr, "  - %s\n", f)
   444→		}
   445→		fmt.Fprintf(os.Stderr, "\n")
   446→	}
   447→
   448→	// Perform the rewind
   449→	if err := start.Rewind(*selectedPoint); err != nil {
   450→		return err
   451→	}
   452→
   453→	// Handle transcript restoration
   454→	var sessionID string
   455→	var transcriptFile string
   456→
   457→	if selectedPoint.IsTaskCheckpoint {
   458→		checkpoint, err := start.GetTaskCheckpoint(*selectedPoint)
   459→		if err != nil {
   460→			fmt.Fprintf(os.Stderr, "Warning: failed to read task checkpoint: %v\n", err)
   461→			return nil
   462→		}
   463→
   464→		sessionID = checkpoint.SessionID
   465→
   466→		if checkpoint.CheckpointUUID != "" {
   467→			// Use strategy-based transcript restoration for task checkpoints
   468→			if err := restoreTaskCheckpointTranscript(start, *selectedPoint, sessionID, checkpoint.CheckpointUUID); err != nil {
   469→				fmt.Fprintf(os.Stderr, "Warning: failed to restore truncated session transcript: %v\n", err)
   470→			} else {
   471→				fmt.Printf("Rewound to task checkpoint. %s\n", formatResumeCommand(sessionID, selectedPoint.Agent))
   472→			}
   473→			return nil
   474→		}
   475→	} else {
   476→		sessionID = extractSessionIDFromMetadata(selectedPoint.MetadataDir)
   477→		transcriptFile = filepath.Join(selectedPoint.MetadataDir, paths.TranscriptFileNameLegacy)
   478→	}
   479→
   480→	// Try to restore using GetSessionLog first (for strategies that store transcripts in git)
   481→	// Use checkpoint ID if available (auto-commit strategy), otherwise use commit ID (manual-commit strategy)
   482→	lookupID := selectedPoint.CheckpointID
   483→	if lookupID == "" {
   484→		lookupID = selectedPoint.ID
   485→	}
   486→	if returnedSessionID, err := restoreSessionTranscriptFromStrategy(start, lookupID, sessionID, selectedPoint.Agent); err != nil {
   487→		// Fall back to local file
   488→		if err := restoreSessionTranscript(transcriptFile, sessionID, selectedPoint.Agent); err != nil {
   489→			fmt.Fprintf(os.Stderr, "Warning: failed to restore session transcript: %v\n", err)
   490→		}
   491→	} else {
   492→		// Use session ID returned from strategy (may differ from what we extracted from metadata path)
   493→		sessionID = returnedSessionID
   494→	}
   495→
   496→	fmt.Printf("Rewound to %s. %s\n", selectedPoint.ID[:7], formatResumeCommand(sessionID, selectedPoint.Agent))
   497→	return nil
   498→}
