   500→// handleLogsOnlyRewindNonInteractive handles logs-only rewind in non-interactive mode.
   501→// Defaults to restoring logs only (no checkout) for safety.
   502→func handleLogsOnlyRewindNonInteractive(start strategy.Strategy, point strategy.RewindPoint) error {
   503→	restorer, ok := start.(strategy.LogsOnlyRestorer)
   504→	if !ok {
   505→		return errors.New("strategy does not support logs-only restoration")
   506→	}
   507→
   508→	if err := restorer.RestoreLogsOnly(point, true); err != nil { // force=true for explicit rewind
   509→		return fmt.Errorf("failed to restore logs: %w", err)
   510→	}
   511→
   512→	// Show resume commands for all sessions
   513→	printMultiSessionResumeCommands(point)
   514→
   515→	fmt.Println("Note: Working directory unchanged. Use interactive mode for full checkout.")
   516→	return nil
   517→}
