   519→// handleLogsOnlyResetNonInteractive handles reset in non-interactive mode.
   520→// This performs a git reset --hard to the target commit.
   521→func handleLogsOnlyResetNonInteractive(start strategy.Strategy, point strategy.RewindPoint) error {
   522→	restorer, ok := start.(strategy.LogsOnlyRestorer)
   523→	if !ok {
   524→		return errors.New("strategy does not support logs-only restoration")
   525→	}
   526→
   527→	// Get current HEAD before reset (for recovery message)
   528→	currentHead, err := getCurrentHeadHash()
   529→	if err != nil {
   530→		currentHead = ""
   531→	}
   532→
   533→	// Restore logs first
   534→	if err := restorer.RestoreLogsOnly(point, true); err != nil { // force=true for explicit rewind
   535→		return fmt.Errorf("failed to restore logs: %w", err)
   536→	}
   537→
   538→	// Perform git reset --hard
   539→	if err := performGitResetHard(point.ID); err != nil {
   540→		return fmt.Errorf("failed to reset branch: %w", err)
   541→	}
   542→
   543→	shortID := point.ID
   544→	if len(shortID) > 7 {
   545→		shortID = shortID[:7]
   546→	}
   547→
   548→	fmt.Printf("Reset branch to %s.\n", shortID)
   549→
   550→	// Show resume commands for all sessions
   551→	printMultiSessionResumeCommands(point)
   552→
   553→	// Show recovery instructions
   554→	if currentHead != "" && currentHead != point.ID {
   555→		currentShort := currentHead
   556→		if len(currentShort) > 7 {
   557→			currentShort = currentShort[:7]
   558→		}
   559→		fmt.Printf("\nTo undo this reset: git reset --hard %s\n", currentShort)
   560→	}
   561→
   562→	return nil
   563→}
