   565→func extractSessionIDFromMetadata(metadataDir string) string {
   566→	// Metadata dir format varies by strategy:
   567→	// - manual-commit/commit: .entire/metadata/2025-01-25-<session-id>
   568→	// - auto-commit: ab/cdef1234.../2025-11-28-<session-id>
   569→	base := filepath.Base(metadataDir)
   570→	// Try to extract UUID from the end (format: YYYY-MM-DD-uuid)
   571→	parts := strings.SplitN(base, "-", 4)
   572→	if len(parts) >= 4 {
   573→		return parts[3]
   574→	}
   575→	return base
   576→}
