   578→func restoreSessionTranscript(transcriptFile, sessionID, agentType string) error {
   579→	// Get the agent for session directory and ID transformation
   580→	ag, err := agent.GetByAgentType(agentType)
   581→	if err != nil {
   582→		return fmt.Errorf("failed to get agent for type %q: %w", agentType, err)
   583→	}
   584→
   585→	// Get repo root for agent's session directory lookup
   586→	// Use repo root instead of CWD because Claude stores sessions per-repo,
   587→	// and running from a subdirectory would look up the wrong session directory
   588→	repoRoot, err := paths.RepoRoot()
   589→	if err != nil {
   590→		return fmt.Errorf("failed to get repository root: %w", err)
   591→	}
   592→
   593→	// Get agent's session storage directory
   594→	sessionDir, err := ag.GetSessionDir(repoRoot)
   595→	if err != nil {
   596→		return fmt.Errorf("failed to get agent session directory: %w", err)
   597→	}
   598→
   599→	// Ensure session directory exists
   600→	if err := os.MkdirAll(sessionDir, 0o750); err != nil {
   601→		return fmt.Errorf("failed to create agent session directory: %w", err)
   602→	}
   603→
   604→	// Extract agent's session ID format from Entire session ID
   605→	agentSessionID := ag.ExtractAgentSessionID(sessionID)
   606→	sessionFile := filepath.Join(sessionDir, agentSessionID+".jsonl")
   607→	fmt.Fprintf(os.Stderr, "Copying transcript:\n  From: %s\n  To: %s\n", transcriptFile, sessionFile)
   608→	if err := copyFile(transcriptFile, sessionFile); err != nil {
   609→		return fmt.Errorf("failed to copy transcript: %w", err)
   610→	}
   611→
   612→	return nil
   613→}
   614→
   615→// restoreSessionTranscriptFromStrategy restores a session transcript using GetSessionLog.
   616→// This is used for strategies that store transcripts in git branches rather than local files.
