   848→// handleLogsOnlyReset restores logs and resets the branch to the commit (destructive).
   849→func handleLogsOnlyReset(start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
   850→	// First, restore the logs
   851→	restorer, ok := start.(strategy.LogsOnlyRestorer)
   852→	if !ok {
   853→		return errors.New("strategy does not support logs-only restoration")
   854→	}
   855→
   856→	if err := restorer.RestoreLogsOnly(point, true); err != nil { // force=true for explicit rewind
   857→		return fmt.Errorf("failed to restore logs: %w", err)
   858→	}
   859→
   860→	// Get current HEAD before reset (for recovery message)
   861→	currentHead, err := getCurrentHeadHash()
   862→	if err != nil {
   863→		// Non-fatal - just won't show recovery message
   864→		currentHead = ""
   865→	}
   866→
   867→	// Get detailed uncommitted changes warning from strategy
   868→	var uncommittedWarning string
   869→	if _, warn, err := start.CanRewind(); err == nil {
   870→		uncommittedWarning = warn
   871→	}
   872→
   873→	// Check for safety issues
   874→	warnings, err := checkResetSafety(point.ID, uncommittedWarning)
   875→	if err != nil {
   876→		return fmt.Errorf("failed to check reset safety: %w", err)
   877→	}
   878→
   879→	// Build confirmation message based on warnings
   880→	var confirmTitle, confirmDesc string
   881→	if len(warnings) > 0 {
   882→		confirmTitle = "⚠️  Reset branch with warnings?"
   883→		confirmDesc = "WARNING - the following issues were detected:\n" +
   884→			strings.Join(warnings, "\n") +
   885→			"\n\nThis will move your branch to " + shortID + " and DISCARD commits after it!"
   886→	} else {
   887→		confirmTitle = "Reset branch to " + shortID + "?"
   888→		confirmDesc = "This will move your branch pointer to this commit.\nCommits after this point will be orphaned (but recoverable via reflog)."
   889→	}
   890→
   891→	var confirm bool
   892→	confirmForm := NewAccessibleForm(
   893→		huh.NewGroup(
   894→			huh.NewConfirm().
   895→				Title(confirmTitle).
   896→				Description(confirmDesc).
   897→				Value(&confirm),
   898→		),
   899→	)
   900→
   901→	if err := confirmForm.Run(); err != nil {
   902→		return fmt.Errorf("confirmation cancelled: %w", err)
   903→	}
   904→
   905→	if !confirm {
   906→		fmt.Println("Reset cancelled. Session logs were still restored.")
   907→		printMultiSessionResumeCommands(point)
   908→		return nil
   909→	}
   910→
   911→	// Perform git reset --hard
   912→	if err := performGitResetHard(point.ID); err != nil {
   913→		return fmt.Errorf("failed to reset branch: %w", err)
   914→	}
   915→
   916→	fmt.Printf("Reset branch to %s.\n", shortID)
   917→	printMultiSessionResumeCommands(point)
   918→
   919→	// Show recovery instructions
   920→	if currentHead != "" && currentHead != point.ID {
   921→		currentShort := currentHead
   922→		if len(currentShort) > 7 {
   923→			currentShort = currentShort[:7]
   924→		}
   925→		fmt.Printf("\nTo undo this reset: git reset --hard %s\n", currentShort)
   926→	}
   927→
   928→	return nil
   929→}
