   931→// getCurrentHeadHash returns the current HEAD commit hash.
   932→func getCurrentHeadHash() (string, error) {
   933→	repo, err := openRepository()
   934→	if err != nil {
   935→		return "", err
   936→	}
   937→
   938→	head, err := repo.Head()
   939→	if err != nil {
   940→		return "", fmt.Errorf("failed to get HEAD: %w", err)
   941→	}
