   946→// checkResetSafety checks for potential issues before a git reset --hard.
   947→// Returns a list of warning messages (empty if safe to proceed without warnings).
   948→// If uncommittedChangesWarning is provided, it will be used instead of a generic warning.
   949→func checkResetSafety(targetCommitHash string, uncommittedChangesWarning string) ([]string, error) {
   950→	var warnings []string
   951→
   952→	repo, err := openRepository()
   953→	if err != nil {
   954→		return nil, err
   955→	}
   956→
   957→	// Check for uncommitted changes
   958→	if uncommittedChangesWarning != "" {
   959→		// Use the detailed warning from strategy's CanRewind()
   960→		warnings = append(warnings, uncommittedChangesWarning)
   961→	} else {
   962→		// Fall back to generic check
   963→		worktree, err := repo.Worktree()
   964→		if err != nil {
   965→			return nil, fmt.Errorf("failed to get worktree: %w", err)
   966→		}
   967→
   968→		status, err := worktree.Status()
   969→		if err != nil {
   970→			return nil, fmt.Errorf("failed to get status: %w", err)
   971→		}
   972→
   973→		if !status.IsClean() {
   974→			warnings = append(warnings, "• You have uncommitted changes that will be LOST")
   975→		}
   976→	}
   977→
   978→	// Check if current HEAD is ahead of target (we'd be discarding commits)
   979→	head, err := repo.Head()
   980→	if err != nil {
   981→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
   982→	}
   983→
   984→	targetHash := plumbing.NewHash(targetCommitHash)
   985→
   986→	// Count commits between target and HEAD
   987→	commitsAhead, err := countCommitsBetween(repo, targetHash, head.Hash())
   988→	if err != nil {
   989→		// Non-fatal - just can't show commit count
   990→		commitsAhead = -1
   991→	}
   992→
   993→	if commitsAhead > 0 {
   994→		warnings = append(warnings, fmt.Sprintf("• %d commit(s) after this point will be orphaned", commitsAhead))
   995→	}
   996→
   997→	return warnings, nil
   998→}
