  1000→// countCommitsBetween counts commits between ancestor and descendant.
  1001→// Returns 0 if ancestor == descendant, -1 on error.
  1002→func countCommitsBetween(repo *git.Repository, ancestor, descendant plumbing.Hash) (int, error) {
  1003→	if ancestor == descendant {
  1004→		return 0, nil
  1005→	}
  1006→
  1007→	// Walk from descendant back to ancestor
  1008→	count := 0
  1009→	current := descendant
  1010→
  1011→	for count < 1000 { // Safety limit
  1012→		if current == ancestor {
  1013→			return count, nil
  1014→		}
  1015→
  1016→		commit, err := repo.CommitObject(current)
  1017→		if err != nil {
  1018→			return -1, fmt.Errorf("failed to get commit: %w", err)
  1019→		}
  1020→
  1021→		if commit.NumParents() == 0 {
  1022→			// Reached root without finding ancestor - ancestor not in history
  1023→			return -1, nil
  1024→		}
  1025→
  1026→		count++
  1027→		current = commit.ParentHashes[0] // Follow first parent
  1028→	}
  1029→
  1030→	return -1, nil
  1031→}
