  1033→// performGitResetHard performs a git reset --hard to the specified commit.
  1034→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1035→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1036→func performGitResetHard(commitHash string) error {
  1037→	ctx := context.Background()
  1038→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", commitHash)
  1039→	if output, err := cmd.CombinedOutput(); err != nil {
  1040→		return fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1041→	}
  1042→	return nil
  1043→}
