  1079→// sanitizeForTerminal removes or replaces characters that cause rendering issues
  1080→// in terminal UI components. This includes emojis with skin-tone modifiers and
  1081→// other multi-codepoint characters that confuse width calculations.
  1082→func sanitizeForTerminal(s string) string {
  1083→	var result strings.Builder
  1084→	result.Grow(len(s))
  1085→
  1086→	for _, r := range s {
  1087→		// Skip emoji skin tone modifiers (U+1F3FB to U+1F3FF)
  1088→		if r >= 0x1F3FB && r <= 0x1F3FF {
  1089→			continue
  1090→		}
  1091→		// Skip zero-width joiners used in emoji sequences
  1092→		if r == 0x200D {
  1093→			continue
  1094→		}
  1095→		// Skip variation selectors (U+FE00 to U+FE0F)
  1096→		if r >= 0xFE00 && r <= 0xFE0F {
  1097→			continue
  1098→		}
  1099→		// Keep printable characters and common whitespace
  1100→		if unicode.IsPrint(r) || r == '\t' || r == '\n' {
  1101→			result.WriteRune(r)
  1102→		}
  1103→	}
  1104→
  1105→	return result.String()
  1106→}
