  1121→// printMultiSessionResumeCommands prints resume commands for all sessions in a rewind point.
  1122→// For single-session checkpoints, prints a single resume command.
  1123→// For multi-session checkpoints, prints all sessions with prompts as comments.
  1124→func printMultiSessionResumeCommands(point strategy.RewindPoint) {
  1125→	// Check if this is a multi-session checkpoint
  1126→	if point.SessionCount > 1 && len(point.SessionIDs) > 1 {
  1127→		fmt.Printf("\nRestored %d sessions. Resume with:\n", point.SessionCount)
  1128→
  1129→		// Print each session with prompt as comment
  1130→		for i, sessionID := range point.SessionIDs {
  1131→			cmd := formatResumeCommand(sessionID, point.Agent)
  1132→
  1133→			// Get prompt for this session (if available)
  1134→			var prompt string
  1135→			if i < len(point.SessionPrompts) {
  1136→				prompt = point.SessionPrompts[i]
  1137→			}
  1138→
  1139→			// Add "(most recent)" label to the last session
  1140→			if i == len(point.SessionIDs)-1 {
  1141→				if prompt != "" {
  1142→					fmt.Printf("  %s  # %s (most recent)\n", cmd, prompt)
  1143→				} else {
  1144→					fmt.Printf("  %s  # (most recent)\n", cmd)
  1145→				}
  1146→			} else {
  1147→				if prompt != "" {
  1148→					fmt.Printf("  %s  # %s\n", cmd, prompt)
  1149→				} else {
  1150→					fmt.Printf("  %s\n", cmd)
  1151→				}
  1152→			}
  1153→		}
  1154→	} else {
  1155→		// Single session - use traditional format with prompt if available
  1156→		sessionID := point.SessionID
  1157→		if sessionID == "" && len(point.SessionIDs) > 0 {
  1158→			sessionID = point.SessionIDs[len(point.SessionIDs)-1]
  1159→		}
  1160→		if sessionID != "" {
  1161→			cmd := formatResumeCommand(sessionID, point.Agent)
  1162→			if point.SessionPrompt != "" {
  1163→				fmt.Printf("%s  # %s\n", cmd, point.SessionPrompt)
  1164→			} else {
  1165→				fmt.Printf("%s\n", cmd)
  1166→			}
  1167→		}
  1168→	}
  1169→}
